#!/bin/sh
set -e
cat > /tmp/dk2-payload.b64 <<'DK_PAYLOAD_EOF'

DK_PAYLOAD_EOF
base64 -d /tmp/dk2-payload.b64 | tar -xz
rm -f /tmp/dk2-payload.b64
cat > package.json <<'DK_PKG_EOF'
{
  "name": "dramaku",
  "version": "1.0.0",
  "private": true,
  "description": "Web streaming drama pendek — Next.js + Tailwind + Framer Motion",
  "scripts": {
    "dev": "next dev -H 0.0.0.0",
    "build": "next build",
    "start": "next start",
    "lint": "next lint"
  },
  "dependencies": {
    "cheerio": "^1.0.0",
    "framer-motion": "^11.11.9",
    "next": "^14.2.5",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@types/node": "^20.14.12",
    "@types/react": "^18.3.3",
    "@types/react-dom": "^18.3.0",
    "autoprefixer": "^10.4.19",
    "postcss": "^8.4.40",
    "tailwindcss": "^3.4.7",
    "typescript": "^5.5.4"
  }
}
DK_PKG_EOF
cat > tsconfig.json <<'DK_TSCONFIG_EOF'
{
  "compilerOptions": {
    "target": "es2017",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": false,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [{ "name": "next" }],
    "paths": { "@/*": ["./src/*"] }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}
DK_TSCONFIG_EOF
npm install --no-audit --no-fund
